import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String tenantId = (String) req.getSession().getAttribute("tenant_id");

        if (tenantId == null) {
            resp.sendError(401);
            return;
        }

        // Validate report type against whitelist
        if (!Pattern.matches("^(sales|inventory|audit|payroll)$", reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (!Pattern.matches("^\\d{4}-\\d{2}-\\d{2}$", startDate) ||
            !Pattern.matches("^\\d{4}-\\d{2}-\\d{2}$", endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column - allow alphanumeric and underscore
        if (sortCol != null && !Pattern.matches("^[a-zA-Z_]{1,30}$", sortCol)) {
            sortCol = "created_at";
        }
        if (sortCol == null) sortCol = "created_at";

        String query = "SELECT id, description, amount, created_at FROM " + reportType + "_reports" +
                       " WHERE tenant_id = '" + tenantId + "'" +
                       " AND created_at BETWEEN '" + startDate + "' AND '" + endDate + "'" +
                       " ORDER BY " + sortCol;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"description\": \"%s\", \"amount\": %.2f, \"created_at\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("description").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String tenantId = (String) req.getSession().getAttribute("tenant_id");
        if (tenantId == null) { resp.sendError(401); return; }

        String description = req.getParameter("description");
        String amount = req.getParameter("amount");
        String category = req.getParameter("category");

        // Basic length check
        if (description == null || description.length() > 500) {
            resp.sendError(400); return;
        }

        String insert = "INSERT INTO sales_reports (tenant_id, description, amount, category, created_at) " +
                        "VALUES ('" + tenantId + "', '" + description + "', " + amount + ", '" + category + "', NOW())";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            stmt.executeUpdate(insert);
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500, "Insert failed");
        }
    }
}
